  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the sand's grain: fine bumps, and here and there a pit, each fading to its mean where finer than a pixel
    float cmF = kfade(2.0 / p_cmSand);
    float cmG = mix(0.5, kn(uv * p_cmSand + seed), cmF);
    float cmG2 = mix(0.5, kn(uv * p_cmSand * 0.43 + seed + 5.0), kfade(4.0 / p_cmSand));
    float cmP = p_cmPits * (1.0 - smoothstep(0.0, 0.22, kcell(uv * p_cmSand * 0.3 + seed + 3.0))) * kfade(8.0 / p_cmSand);
    // the faces that look down (wn.y below 0) carry the oil and road grime, the rest a little of it in patches
    float cmDown = smoothstep(0.15, -0.85, wn.y);
    float cmGr = clamp(p_cmGrime * (0.2 + 0.9 * cmDown) * smoothstep(0.3, 0.75, kfbm(uv * 4.5 + seed + 7.0) + 0.3 * cmDown), 0.0, 1.0);
    float cmB = p_cmBloom * smoothstep(0.45, 0.85, kfbm4(uv * 3.0 + seed + 1.0));
    float cmH = p_cmHeat * smoothstep(0.25, 0.75, kfbm4(uv * 2.2 + seed + 13.0));
    float cmS = 0.6 * cmG + 0.4 * cmG2;
    vec3 cmC = p_cmColour * (0.9 + 0.2 * cmS) * (1.0 - 0.45 * cmP);
    cmC = mix(cmC, p_cmBloomColour, cmB);
    cmC = mix(cmC, p_cmHeatColour * (0.85 + 0.3 * cmS), cmH);
    cmC = mix(cmC, p_cmGrimeColour, clamp(cmGr + 0.6 * cmP * p_cmGrime, 0.0, 1.0));
    k.colour = cmC;
    k.metal = p_cmMetal * (1.0 - 0.5 * cmB) * (1.0 - 0.8 * cmGr);
    k.rough = clamp(p_cmRough + 0.12 * (cmS - 0.5) + 0.2 * cmB + 0.25 * cmGr + 0.2 * cmP, 0.05, 1.0);
    k.height = p_cmRelief * (cmS - 0.5 - 0.9 * cmP) + 0.00003 * cmGr;
    k.ao = 1.0 - 0.35 * cmP;
