    k.rough = clamp(p_htRough + 0.1 * (htFine - 0.5) + 0.12 * smoothstep(0.8, 1.0, htH) + 0.5 * htS, 0.03, 1.0);
    k.height = 0.000012 * (htFine - 0.5) + 0.00008 * htS * kn(uv * 300.0 + seed);
    vec3 htV = normalize(wp - cameraPosition);
    vec3 htNn = normalize(wn);
    vec3 htR = reflect(htV, htNn) + 0.06 * (htFine - 0.5) * vec3(1.0, 0.0, 1.0);
