  vec3 wn = normalize(vLookWN);

    float ucDown = smoothstep(0.0, -0.8, wn.y);
    float ucUp = smoothstep(0.3, 0.95, wn.y);
    float ucB = kfbm(uv * 4.0 + seed);
    float ucG = clamp(p_ucGrime * (0.3 + 0.9 * ucDown) * smoothstep(0.3, 0.75, ucB + 0.25 * ucDown), 0.0, 1.0);
    float ucD = clamp(p_ucDust * ucUp * smoothstep(0.35, 0.8, kfbm4(uv * 7.0 + seed + 4.0)), 0.0, 1.0);
    // chips gather in patches (a slow field) and are each a small blot (a fast one), so they cluster on a part
    float ucPatch = smoothstep(0.55, 0.8, kfbm4(uv * 1.5 + seed + 21.0));
    float ucChipN = (kn(uv * 70.0 + seed + 9.0) + 0.15 * kn(uv * 300.0 + seed)) * kfade(0.02);
    float ucChip = ucPatch * smoothstep(1.06 - 0.12 * p_ucChips, 1.1 - 0.12 * p_ucChips, ucChipN);
    float ucO = p_ucOil * smoothstep(0.55, 0.85, kfbm4(uv * 2.0 + seed + 11.0));
    k.colour = mix(p_ucColour, p_ucGrimeColour, ucG);
    k.colour = mix(k.colour, p_ucDustColour, ucD);
    k.colour = mix(k.colour, p_ucRust * (0.7 + 0.6 * kn(uv * 200.0 + seed)), ucChip);
    k.colour = mix(k.colour, vec3(0.01, 0.008, 0.006), ucO);
    k.rough = clamp(p_ucRough + 0.35 * ucG + 0.3 * ucD + 0.35 * ucChip - 0.4 * ucO, 0.05, 1.0);
    k.metal = 0.0;
    k.height = 0.00015 * ucG * ucB - 0.0001 * ucChip;

}

void look_38(inout Look k) {
  p_bmColour = L38_bmColour;
  p_bmLines = L38_bmLines;
  p_bmStreak = L38_bmStreak;
  p_bmLong = L38_bmLong;
  p_bmRough = L38_bmRough;
  p_bmMetal = L38_bmMetal;
  p_bmRelief = L38_bmRelief;
  p_bmMirror = L38_bmMirror;
  p_bmSky = L38_bmSky;
  p_bmWall = L38_bmWall;
  p_bmFloor = L38_bmFloor;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 bmG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the brushing, across it
    vec2 bmQ = vec2(dot(uv, bmG), dot(uv, vec2(-bmG.y, bmG.x)));
    // the scratches: noise stretched far along the brushing, one row a scratch, faded to its mean where a scratch is
    // under a pixel; a few deeper, longer ones over them
    float bmFine = mix(0.5, kn(vec2(bmQ.x * p_bmLong * 4.0, bmQ.y * p_bmLines) + seed), kfade(2.0 / p_bmLines));
    float bmDeep = mix(0.5, kn(vec2(bmQ.x * p_bmLong, bmQ.y * p_bmLines * 0.18) + seed + 17.0), kfade(8.0 / p_bmLines));
    float bmS = 0.75 * bmFine + 0.25 * smoothstep(0.35, 0.8, bmDeep);
    // a slow cloud of the belt's passes, so a big sheet isn't one flat grey
    float bmPass = kfbm4(vec2(bmQ.x * 0.6, bmQ.y * 7.0) + seed * 1.3);
    vec3 bmC = p_bmColour * (1.0 + p_bmStreak * (bmS - 0.5) * 0.9) * (0.94 + 0.12 * bmPass);
    k.colour = bmC;
    k.metal = p_bmMetal;
    k.rough = clamp(p_bmRough + 0.12 * (bmS - 0.5) + 0.05 * (bmPass - 0.5), 0.03, 1.0);
    k.height = p_bmRelief * (bmS - 0.5);
    // the room mirrored, smeared along the brushing: its ray tipped across the scratches by each one's slope
    vec3 bmV = normalize(wp - cameraPosition);
    vec3 bmN = normalize(wn);
    vec3 bmR = reflect(bmV, bmN);
    float bmCos = clamp(dot(-bmV, bmN), 0.0, 1.0);
    float bmFres = 0.7 + 0.3 * pow(1.0 - bmCos, 3.0);
    vec3 bmRoom = rmRoom(normalize(bmR + 0.08 * (bmS - 0.5) * vec3(1.0, 0.0, 1.0)), clamp(p_bmRough * 2.2, 0.0, 1.0), p_bmSky, p_bmWall, p_bmFloor);
    k.glow = p_bmMirror * bmRoom * bmC * bmFres * (0.85 + 0.3 * bmS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(0.5 + 0.5 * bmG.x, 0.5 + 0.5 * bmG.y, 0.5);

}

