void look_6(inout Look k) {
  p_cpColour = L6_cpColour;
  p_cpCrown = L6_cpCrown;
  p_cpWrinkles = L6_cpWrinkles;
  p_cpWander = L6_cpWander;
  p_cpRelief = L6_cpRelief;
  p_cpRough = L6_cpRough;
  p_cpCrownRough = L6_cpCrownRough;
  p_cpDust = L6_cpDust;
  p_cpDustColour = L6_cpDustColour;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the net: the edges of cells in a field warped by noise, so the ridges wander and branch as a wrinkle coat's do;
    // a second, finer net at a slant over it for the small wrinkles between the big ones
    vec2 cpP = uv * p_cpWrinkles + seed * 13.0;
    cpP += p_cpWander * vec2(kn(cpP * 0.35 + 2.0), kn(cpP * 0.35 + 9.0)) * 2.0;
    float cpId, cpE;
    kvor(cpP, cpId, cpE);
    float cpId2, cpE2;
    vec2 cpQ = mat2(0.8, -0.6, 0.6, 0.8) * cpP * 1.9 + 4.0;
    kvor(cpQ, cpId2, cpE2);
    // each net fades to its own mean where its wrinkles are finer than a pixel (the share of the face a ridge covers, as
    // the cells' edges fall), so a face seen from afar is the even satin it looks, with no seam where the fade changes
    float cpF = kfade(1.5 / p_cpWrinkles);
    float cpF2 = kfade(0.8 / p_cpWrinkles);
    float cpRidge = mix(0.3, 1.0 - smoothstep(0.0, 0.32, cpE), cpF);
    float cpRidge2 = mix(0.25, 1.0 - smoothstep(0.0, 0.25, cpE2), cpF2);
    float cpR = max(cpRidge, 0.55 * cpRidge2);
    float cpCr = cpR;
    float cpUp = smoothstep(0.3, 0.9, wn.y);
    float cpD = p_cpDust * cpUp * (1.0 - cpR) * smoothstep(0.35, 0.8, kfbm4(uv * 6.0 + seed + 3.0));
    vec3 cpC = mix(p_cpColour, p_cpCrown, cpCr * (0.7 + 0.6 * cpId));
    cpC = mix(cpC, p_cpDustColour, cpD);
    k.colour = cpC;
    k.metal = 0.0;
    k.rough = clamp(mix(p_cpRough, p_cpCrownRough, cpCr) + 0.3 * cpD, 0.05, 1.0);
    k.height = p_cpRelief * (cpRidge + 0.5 * cpRidge2);
    k.clearcoat = 0.25 * cpCr;
    k.clearcoatRough = 0.35;
    k.ao = 1.0 - 0.25 * (1.0 - cpR) * cpF;

}

