  p_stOilSize = L49_stOilSize;
  p_stOilRough = L49_stOilRough;
  p_stFinPitch = L49_stFinPitch;
  p_stFinShare = L49_stFinShare;
  p_stFinDepth = L49_stFinDepth;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float brush = kn(vec2(uv.x * 4.0, uv.y * 900.0) + seed) * kfade(0.002);
    float wear = kfbm(uv * 3.0 + seed);
    vec3 stC = p_stColour * (0.9 + 0.12 * brush) * (0.9 + 0.15 * wear);
    float stM = p_stMetal;
    float stR = p_stRough + 0.15 * brush + 0.1 * wear;
    float stH = 0.00005 * brush;
    // fins: a rounded ridge of share stFinShare in each pitch along s3.x, the groove between them the depth down and
    // dark (the normal they bend is worked out below); fading to the fins' mean where a pitch is under a few pixels
    float stOn = step(0.5, s3.y);
    float stFade = kfade(p_stFinPitch * 4.0);
    float stF = fract(s3.x / p_stFinPitch);
    float stRidge = smoothstep(1.0 - 2.0 * p_stFinShare, 1.0, 0.5 + 0.5 * cos(6.28318 * stF));
    // far off, the fins' mean: the ridges' share lit, the rest groove
    float stShade = mix(p_stFinShare, stRidge, stFade);
    stC *= mix(1.0, 0.55 + 0.45 * stShade, stOn);
    // burnt castor oil: blotches and runs of a brown-black varnish; thick (glossy, brown in its highlight) or thin
    float stBlot = kfbm(uv * p_stOilSize + seed * 1.7);
    float stRun = kn(vec2(uv.x * p_stOilSize * 0.6, uv.y * p_stOilSize * 9.0) + seed + 11.0);
    float stThick = smoothstep(0.35, 0.75, 0.65 * stBlot + 0.35 * stRun);
    float stO = clamp(p_stOil * (0.75 + 0.35 * stThick), 0.0, 1.0);
    vec3 stOilC = mix(p_stOilColour, p_stOilBrown, stThick * (0.5 + 0.5 * kn(uv * 60.0 + seed)));
    stC = mix(stC, stOilC * mix(1.0, 0.6 + 0.4 * stShade, stOn), stO);
    stM = mix(stM, 0.12, stO);
    stR = mix(stR, mix(0.75, p_stOilRough, stThick), stO);
    stH += p_stOil * 0.00004 * stThick;
    k.colour = stC;
    k.metal = stM;
    k.rough = stR;
    k.height = stH;
    if (stOn > 0.5) {
      // the fins bend the normal from their profile's slope worked out exactly, not from the pixels' neighbours (whose
      // steps break thin rings into dots): the way s3.x grows across the surface, in the view's ways, from its change
      // between pixels (it is even across a face, so this is clean), times the profile's slope along it
      vec3 stN = normalize(vNormal);
      vec3 stPx = dFdx(-vViewPosition), stPy = dFdy(-vViewPosition);
      vec3 stR1 = cross(stPy, stN), stR2 = cross(stN, stPx);
      float stDet = dot(stPx, stR1);
      vec3 stG = (dFdx(s3.x) * stR1 + dFdy(s3.x) * stR2) / (abs(stDet) > 1e-14 ? stDet : 1e-14);
      float stPhi = 6.28318 * stF;
      float stA = 1.0 - 2.0 * p_stFinShare;
      float stT = clamp((0.5 + 0.5 * cos(stPhi) - stA) / (1.0 - stA), 0.0, 1.0);
      float stSlope = p_stFinDepth * 6.0 * stT * (1.0 - stT) / (1.0 - stA) * (-0.5 * sin(stPhi) * 6.28318 / p_stFinPitch);
      k.normal = normalize(stN - stFade * stSlope * stG);
      k.ownNormal = true;
    }

}

void look_50(inout Look k) {
  p_apColour = L50_apColour;
  p_apFlake = L50_apFlake;
  p_apFlakeColour = L50_apFlakeColour;
  p_apFlakeSize = L50_apFlakeSize;
  p_apRough = L50_apRough;
  p_apCoat = L50_apCoat;
  p_apCoatRough = L50_apCoatRough;
  p_apPeel = L50_apPeel;
  p_apPeelDepth = L50_apPeelDepth;
  p_apDust = L50_apDust;
  p_apDustColour = L50_apDustColour;
  p_apDustHeight = L50_apDustHeight;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // flake: one fleck a cell, each its own brightness and its own tilt, fading to its mean where a fleck is under a pixel
    vec2 apC = floor(uv / p_apFlakeSize);
    float apS = kh(apC + seed);
    float apSee = kfade(p_apFlakeSize * 3.0);
    float apFleck = mix(0.5, step(0.55, apS) * (0.4 + 0.6 * kh(apC + seed + 17.0)), apSee) * p_apFlake;
    vec3 apBase = p_apColour * (0.97 + 0.06 * kfbm4(uv * 1.5 + seed));
    k.colour = mix(apBase, apBase * 0.4 + p_apFlakeColour * 0.6, apFleck * 0.35);
    k.metal = p_apFlake * 0.6;
    k.rough = clamp(p_apRough - 0.15 * apFleck, 0.0, 1.0);
    float apPeelF = kfade(2.0 / p_apPeel);
    float apP = (1.0 - kcell(uv * p_apPeel + seed)) * apPeelF;
    k.height = p_apPeelDepth * apP + 0.000004 * (apS - 0.5) * apSee * p_apFlake;
    k.clearcoat = p_apCoat;
    k.clearcoatRough = p_apCoatRough;
    // road dust: thick at the ground, gone by apDustHeight, broken up so it reads as spray, not a band
    float apLow = 1.0 - smoothstep(0.0, p_apDustHeight, wp.y);
    float apSpray = smoothstep(0.25, 0.85, kfbm(uv * 6.0 + seed + 3.0) + 0.35 * apLow);
    float apD = clamp(p_apDust * apLow * apSpray * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_apDustColour * (0.85 + 0.3 * kn(uv * 60.0 + seed)), apD);
    k.rough = mix(k.rough, 0.85, apD);
    k.metal = mix(k.metal, 0.0, apD);
    k.clearcoat = mix(k.clearcoat, 0.0, apD);

}

void look_51(inout Look k) {
  p_tpColour = L51_tpColour;
  p_tpFaded = L51_tpFaded;
  p_tpFade = L51_tpFade;
  p_tpGrain = L51_tpGrain;
  p_tpGrainDepth = L51_tpGrainDepth;
  p_tpRough = L51_tpRough;
  p_tpDust = L51_tpDust;
  p_tpDustColour = L51_tpDustColour;
  p_tpDustHeight = L51_tpDustHeight;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float tpSee = kfade(2.0 / p_tpGrain);
    float tpId, tpEdge;
    kvor(uv * p_tpGrain + seed, tpId, tpEdge);
    float tpRim = (1.0 - smoothstep(0.0, 0.18, tpEdge)) * tpSee;
    float tpCell = (kh1(tpId) - 0.5) * tpSee;
    float tpUp = smoothstep(0.2, 0.9, wn.y);
    float tpF = p_tpFade * tpUp * (0.7 + 0.3 * kfbm4(uv * 3.0 + seed));
    k.colour = mix(p_tpColour, p_tpFaded, tpF) * (1.0 + 0.12 * tpCell - 0.15 * tpRim);
    k.rough = clamp(p_tpRough + 0.1 * tpF - 0.08 * tpRim, 0.0, 1.0);
    k.height = p_tpGrainDepth * (0.6 * tpRim + 0.4 * tpCell);
    float tpLow = 1.0 - smoothstep(0.0, p_tpDustHeight, wp.y);
    float tpD = clamp(p_tpDust * tpLow * smoothstep(0.3, 0.8, kfbm(uv * 5.0 + seed + 7.0) + 0.3 * tpLow) * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_tpDustColour, tpD);
    k.rough = mix(k.rough, 0.9, tpD);

}

void look_52(inout Look k) {
  p_pmColour = L52_pmColour;
  p_pmPeel = L52_pmPeel;
  p_pmRelief = L52_pmRelief;
  p_pmRough = L52_pmRough;
  p_pmCoat = L52_pmCoat;
  p_pmCoatRough = L52_pmCoatRough;
  p_pmOil = L52_pmOil;
  p_pmOilColour = L52_pmOilColour;
  p_pmOilStreaks = L52_pmOilStreaks;
  p_pmOilRough = L52_pmOilRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_53(inout Look k) {
  p_ucColour = L53_ucColour;
  p_ucRough = L53_ucRough;
  p_ucGrime = L53_ucGrime;
  p_ucGrimeColour = L53_ucGrimeColour;
  p_ucDust = L53_ucDust;
  p_ucDustColour = L53_ucDustColour;
  p_ucChips = L53_ucChips;
  p_ucRust = L53_ucRust;
  p_ucOil = L53_ucOil;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float ucDown = smoothstep(0.0, -0.8, wn.y);
    float ucUp = smoothstep(0.3, 0.95, wn.y);
    float ucB = kfbm(uv * 4.0 + seed);
    float ucG = clamp(p_ucGrime * (0.3 + 0.9 * ucDown) * smoothstep(0.3, 0.75, ucB + 0.25 * ucDown), 0.0, 1.0);
    float ucD = clamp(p_ucDust * ucUp * smoothstep(0.35, 0.8, kfbm4(uv * 7.0 + seed + 4.0)), 0.0, 1.0);
    // chips gather in patches (a slow field) and are each a small blot (a fast one), so they cluster on a part
    float ucPatch = smoothstep(0.55, 0.8, kfbm4(uv * 1.5 + seed + 21.0));
    float ucChipN = (kn(uv * 70.0 + seed + 9.0) + 0.15 * kn(uv * 300.0 + seed)) * kfade(0.02);
    float ucChip = ucPatch * smoothstep(1.06 - 0.12 * p_ucChips, 1.1 - 0.12 * p_ucChips, ucChipN);
    float ucO = p_ucOil * smoothstep(0.55, 0.85, kfbm4(uv * 2.0 + seed + 11.0));
    k.colour = mix(p_ucColour, p_ucGrimeColour, ucG);
    k.colour = mix(k.colour, p_ucDustColour, ucD);
    k.colour = mix(k.colour, p_ucRust * (0.7 + 0.6 * kn(uv * 200.0 + seed)), ucChip);
    k.colour = mix(k.colour, vec3(0.01, 0.008, 0.006), ucO);
    k.rough = clamp(p_ucRough + 0.35 * ucG + 0.3 * ucD + 0.35 * ucChip - 0.4 * ucO, 0.05, 1.0);
    k.metal = 0.0;
    k.height = 0.00015 * ucG * ucB - 0.0001 * ucChip;

}

void look_54(inout Look k) {
  p_glTint = L54_glTint;
  p_glTint2 = L54_glTint2;
  p_glWaves = L54_glWaves;
  p_glWaveDepth = L54_glWaveDepth;
  p_glSeeds = L54_glSeeds;
  p_glRough = L54_glRough;
  p_glAlpha = L54_glAlpha;
  p_glAlphaVar = L54_glAlphaVar;
  p_glRibs = L54_glRibs;
  p_glRibWide = L54_glRibWide;
  p_glRibAlpha = L54_glRibAlpha;
  p_glGlow = L54_glGlow;
  p_glCrease = L54_glCrease;
  p_glCreaseFreq = L54_glCreaseFreq;
  p_glBands = L54_glBands;
  p_glBandHigh = L54_glBandHigh;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float wave = kfbm4(uv * p_glWaves + seed);
    float seeds = smoothstep(0.08, 0.02, kcell(uv * 60.0 + seed)) * kfade(0.01);
    // the twin wall's ribs, along u, one every 1 / glRibs metres across v; under a pixel, their mean cover
    float glRib = 0.0;
    if (p_glRibs > 0.0) {
      float glRd = abs(fract(uv.y * p_glRibs) - 0.5) * 2.0;
      float glRw = fwidth(uv.y * p_glRibs) * 2.0;
      float glLine = 1.0 - smoothstep(p_glRibWide - glRw, p_glRibWide + glRw, 1.0 - glRd);
      glRib = mix(p_glRibWide, glLine, kfade(1.5 / p_glRibs));
    }
    // the film's creases and wound bands, level round the load (the world's height, and the way along the face)
    float glFold = 0.0, glBand = 0.0;
    if (p_glCrease > 0.0 || p_glBands > 0.0) {
      vec3 glSide = cross(vec3(0.0, 1.0, 0.0), wn);
      float glAlong = dot(glSide, glSide) > 0.01 ? dot(wp, normalize(glSide)) : wp.x;
      float glUp = wp.y + 0.03 * kn(vec2(glAlong * 2.0, 0.0) + seed);
      float glF = kn(vec2(glAlong * 1.6, glUp * p_glCreaseFreq) + seed * 1.7);
      float glF2 = kn(vec2(glAlong * 3.1, glUp * p_glCreaseFreq * 2.3) + seed + 5.0);
      glFold = p_glCrease * mix(0.35, pow(1.0 - abs(glF * 2.0 - 1.0), 6.0) * 0.75 + pow(1.0 - abs(glF2 * 2.0 - 1.0), 8.0) * 0.4,
                                kfade(1.0 / p_glCreaseFreq));
      float glB = fract(glUp / p_glBandHigh + 0.15 * kn(vec2(glAlong * 0.8, 3.0) + seed));
      glBand = p_glBands * smoothstep(0.55, 0.62, glB) * (0.8 + 0.4 * kn(vec2(glAlong * 4.0, glUp * 6.0) + seed));
    }
    k.colour = mix(p_glTint, p_glTint2, wave) + seeds * p_glSeeds + vec3(0.12 * glRib + 0.25 * glFold + 0.06 * glBand);
    k.rough = p_glRough + p_glRough * wave;
    k.metal = 0.0;
    k.height = p_glWaveDepth * (wave - 0.5) + 0.0003 * glFold;
    k.alpha = clamp(p_glAlpha + p_glAlphaVar * wave + p_glRibAlpha * glRib + 0.35 * glFold + 0.18 * glBand, 0.0, 1.0);
    k.glow = p_glGlow * (0.9 + 0.2 * wave) * (1.0 + 0.4 * glRib);

}
























































